ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8fc19b6e-0c84-5c23-80e1-98cd28ad6efc', '92dc5a1b-1e92-54b7-9ec7-2d9238d99348', 'b2245dd0-f47e-5875-bb86-90861e677834', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Credit Status', 'Current credit-control disposition. Used by order authorization receivables collections and credit review. Credit control affects exposure and does not alter party identity. SalesOrder confirmation must evaluate current credit policy when applicable. Optional where credit controls are not used. The credit status of the customer is not reviewed; set it when that is what the business means for this record. The credit status of the customer is approved; set it when that is what the business means for this record. The credit status of the customer is on hold; set it when that is what the business means for this record. The credit status of the customer is blocked; set it when that is what the business means for this record.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ce5eccdf-e565-59fe-952e-d1c022ea945e', '92dc5a1b-1e92-54b7-9ec7-2d9238d99348', '18be4623-1692-540a-a834-b065f92d08b4', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Credit Limit', 'Authorized monetary credit exposure limit. Used in credit checks exposure monitoring and risk reporting. Must be interpreted with currency outstanding exposure payment terms and credit status. Provides one input to credit authorization before additional exposure. Optional for cash-only customers.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
