INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d0d6fc62-8588-590b-a86e-e0220297f8d9', '92dc5a1b-1e92-54b7-9ec7-2d9238d99348', '52018b8e-5849-5da5-a5a7-b273d06bd1d4', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Status', 'Lifecycle state of the customer relationship. Controls eligibility for new commercial activity. Historical transactions remain attributable after status changes. New workflows must evaluate status; historical records remain valid. Required for eligibility decisions. The status of the customer is active; set it when that is what the business means for this record. The status of the customer is inactive; set it when that is what the business means for this record. The status of the customer is blocked; set it when that is what the business means for this record. The status of the customer is retired; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2123f8a-d5ac-573a-9188-da1e133d23a2', '92dc5a1b-1e92-54b7-9ec7-2d9238d99348', '4a1a626a-4b22-53b0-a9b7-cfe631bf2f2d', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Party', 'Identifies the underlying person or organization performing this role. Provides common identity without duplicating Party data. One Party may have multiple PartyRoles simultaneously or historically. Connects role-specific processing back to the canonical identity. Required because a role cannot exist without a participant. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
