-- --------------------------------------------------------------------------
-- Lead (bus_lead)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e7bb2011-e583-5f2d-8f16-2f9a721960ce', 'Lead', 'Maintain Lead records', 'Create, find and maintain Lead records. The list shows every Lead you have access to — select a row to open it, or use New to add one. Each row is a single Lead, described by 8 fields.

Id and Lead Number are unique: no two Lead records may share the same value, and a save that would duplicate one is rejected. Lead Number and Status must be filled in before the record can be saved.

Every Lead points at Party, Customer and Opportunity. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Lead then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Lead with no rules or workflows attached is marked Final immediately.', 'target', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'bus_lead', 'Lead', 'Represents a crm entity called Lead within the CEDM business model. Lead is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Lead records. The entity participates in a wider business graph through relationships with Party, Customer, Party, Opportunity. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Lead record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'target', 'A', FALSE, FALSE, FALSE, TRUE, 'e7bb2011-e583-5f2d-8f16-2f9a721960ce', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1adcbb51-f785-53db-998e-43c45f0748aa', 'e7bb2011-e583-5f2d-8f16-2f9a721960ce', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'Lead', 'Shows one Lead at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party, Customer and Opportunity are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ee087622-71b4-5f12-a676-3d1d3c15bd2a', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'id', 'Id', 'Identifies the lead record associated with this Lead. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e16bf2c9-b2a0-5b9d-b4c0-df90fd15cbe3', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'lead_number', 'Lead Number', 'Captures the business meaning of lead number for the Lead. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e97a6a12-5440-5e4a-ba06-31b7c2afbbea', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the new state or classification in the context of Lead. Represents the qualifying state or classification in the context of Lead. Represents the qualified state or classification in the context of Lead. Represents the disqualified state or classification in the context of Lead. Represents the converted state or classification in the context of Lead. Represents the lost state or classification in the context of Lead. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1014, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('665f9bd6-f59b-52ea-91ad-1f7c63b379f5', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'source', 'Source', 'Captures the business meaning of source for the Lead. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ae0121df-8373-52fc-b3bc-8a9b34c9a8ed', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'estimated_value', 'Estimated Value', 'Captures the business meaning of estimated value for the Lead. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
