VALUES ('da216388-7f0a-5039-8f7a-b0028d629a5b', '7de69a61-f853-5855-afdd-2c129a6d293c', 'efdfa73d-1f25-55fa-a7d9-9c8099764257', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Supplier Code', 'Enterprise supplier business reference. Used on purchase orders receipts invoices returns credits payments claims portals reports and integrations. Distinct from legal name and external registration identifiers. Identifies the supplier across procurement settlement recovery and performance. Required for operational recognition. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier already uses this value. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('45a85edc-ac08-545e-bb17-f136d5d4fe79', '7de69a61-f853-5855-afdd-2c129a6d293c', 'b1639bae-73d9-5f4a-8a77-ce22b48cea98', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Supplier Type', 'Classification of supplier relationship. Supports onboarding compliance tax contracting and reporting. Does not replace Party identity classification. Supplies supplier classification to procurement policy. Optional. The supplier type of the supplier is individual; set it when that is what the business means for this record. The supplier type of the supplier is business; set it when that is what the business means for this record. The supplier type of the supplier is government; set it when that is what the business means for this record. The supplier type of the supplier is internal; set it when that is what the business means for this record. The supplier type of the supplier is other; set it when that is what the business means for this record.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d20222f-6b54-56d4-874a-645775404c09', '7de69a61-f853-5855-afdd-2c129a6d293c', 'd61aaafd-4ac9-5b6f-8681-b4c3b4bf5f42', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Qualification Status', 'Procurement qualification state. Controls sourcing eligibility and supplier governance. Qualification is distinct from master lifecycle status and may consume SupplierPerformanceAssessment evidence. Gates new procurement commitments while historical transactions remain valid. Optional where supplier qualification is not used. The qualification status of the supplier is not reviewed; set it when that is what the business means for this record. The qualification status of the supplier is pending; set it when that is what the business means for this record. The qualification status of the supplier is qualified; set it when that is what the business means for this record. The qualification status of the supplier is suspended; set it when that is what the business means for this record. The qualification status of the supplier is disqualified; set it when that is what the business means for this record.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d777093-9579-5d39-bf46-a3184ecd1932', '7de69a61-f853-5855-afdd-2c129a6d293c', '96a5f1a8-a77c-5a88-8ff6-e9ad97116c18', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Payment Terms', 'Default supplier settlement policy. Used by PurchaseOrder Invoice payables payment scheduling and cash forecasting. Transaction or contract terms may override the default. Supplies default payable timing. Optional.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
