ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('253a1fb5-185c-5d69-b02c-595851f19677', '1375b554-82ed-53f7-b573-02964d99f4a1', 'ecca796d-7c9f-53af-8e58-4f11867cdf76', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Code', 'The code of the product category: a value the business records on it. Entered or maintained when a product category is created or changed; shown on its form and available to search and reports. Read together with the product category''s other fields and its relationships; it is not meaningful on its own. Required: a product category cannot be understood without its code. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Product Category already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
