INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9986b500-39cb-5e83-96cf-15b3e20c173c', '1375b554-82ed-53f7-b573-02964d99f4a1', 'ddcb95cd-215d-5cf8-9a15-6b486f84e658', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Status', 'Lifecycle state controlling whether the category can be used for new classification. Set when a category is created and changed as it is taken out of use; filters which categories a product can be classified under. Status changes trigger validation of dependent Products and any rules that consume category classification. The status of the product category is active; set it when that is what the business means for this record. The status of the product category is inactive; set it when that is what the business means for this record. The status of the product category is retired; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4628937e-01aa-5323-b0bf-bd7545b7bc02', '1375b554-82ed-53f7-b573-02964d99f4a1', '40559f99-d34e-5b7e-993d-718a63e1c999', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Parent Category', 'Links a product category to product category, the parent category it relates to. Chosen from the existing product category records when the product category is created or edited. A product category has at most one product category in this role. Lets the product category be found from, and reported with, its product category.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
