INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd26f908-6aaa-5c0c-a96c-6215f3ef2632', '2d9ec52a-c37a-5251-bbda-9dd14a67ae2a', '0a8626ea-943b-57b2-88a6-4359d949292d', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Priority', 'Ordering value used when multiple discount rules qualify. Supports deterministic discount selection or stacking policy. Priority does not itself authorize stacking; the applicable pricing policy must define whether rules can combine. Helps resolve competing discount rules consistently.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
