INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('331029eb-8dee-5814-815b-5bc653f8da0b', '2d9ec52a-c37a-5251-bbda-9dd14a67ae2a', 'a1fce8b5-ccac-5747-b1c3-b2dfc4398622', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Status', 'Controls whether the rule can be selected for new price calculations. Used by pricing and transaction validation. Retiring a rule must not change discounts already recorded on historical transactions. Controls future applicability while preserving historical pricing evidence. The status of the discount rule is draft; set it when that is what the business means for this record. The status of the discount rule is active; set it when that is what the business means for this record. The status of the discount rule is inactive; set it when that is what the business means for this record. The status of the discount rule is retired; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
