INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('deffc47d-af26-54d0-91ff-b41e9dbad546', 'Pricing', 'Maintain Pricing records', 'Create, find and maintain Pricing records. The list shows every Pricing you have access to — select a row to open it, or use New to add one. Each row is a single Pricing, described by 2 fields.

Id is unique: no two Pricing records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Pricing then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Pricing with no rules or workflows attached is marked Final immediately.', 'tag', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9b6e2ff4-1d54-5596-a4ea-43e6c556286c', 'bus_pricing', 'Pricing', 'A governed pricing definition or decision context establishing base prices and applicability conditions before discounts, promotions, quotations, or orders. Provide canonical implementation-neutral semantics for Pricing across enterprise applications. A governed pricing definition or decision context establishing base prices and applicability conditions before discounts, promotions, quotations, or orders. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'tag', 'A', FALSE, FALSE, FALSE, TRUE, 'deffc47d-af26-54d0-91ff-b41e9dbad546', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
