INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('91a2279b-ff6c-532e-8405-b4ca3db10d63', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'status', 'Status', 'Lifecycle state of the authorized customer return. Controls progression through transport, receipt, inspection, disposition, inventory and financial adjustment. Controls return processing and completion decisions. Return status does not itself change inventory or invoice balances. Coordinates dependent return workflows; CreditNote posting is a separate financial state. The status of the customer return is draft; set it when that is what the business means for this record. The status of the customer return is authorized; set it when that is what the business means for this record. The status of the customer return is in transit; set it when that is what the business means for this record. The status of the customer return is received; set it when that is what the business means for this record. The status of the customer return is inspection pending; set it when that is what the business means for this record. The status of the customer return is dispositioned; set it when that is what the business means for this record. The status of the customer return is completed; set it when that is what the business means for this record. The status of the customer return is cancelled; set it when that is what the business means for this record. The status of the customer return is exception; set it when that is what the business means for this record.', 1007, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
