INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ef65551b-e8c8-51ae-b6d1-597b9350d310', 'Brand', 'Maintain Brand records', 'Create, find and maintain Brand records. The list shows every Brand you have access to — select a row to open it, or use New to add one. Each row is a single Brand, described by 4 fields.

Id and Code are unique: no two Brand records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Product refers back to Brand, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Brand then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Brand with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6239192d-6b77-55e0-81b0-b0614027ceaa', 'bus_brand', 'Brand', 'Governed product brand reference master. Brand describes commercial/manufacturer identity; it is distinct from ProductCategory taxonomy and Product identity. PIM, catalog, sourcing, sales, e-commerce, service and analytics. Products and variants reference Brand; category remains independent classification. Active → inactive → active or retired. Lifecycle/name changes update future catalog/master usage while preserving historical references.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'ef65551b-e8c8-51ae-b6d1-597b9350d310', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
