VALUES ('032a08f7-4661-54cf-8805-8d223c86d6ed', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'line_amount', 'Line Amount', 'Calculated commercial value of the line. Supports order totals, invoicing, credit and reporting. Must reconcile with pricing, discount, tax and rounding policy. Financial baseline for downstream billing and reconciliation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
