VALUES ('37838076-e0be-5feb-b0c1-5cb073f8afb0', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'sales_order_id', 'Sales Order', 'Links a sales order line to sales order, the sales order it relates to. Chosen from the existing sales order records when the sales order line is created or edited. A sales order line has exactly one sales order in this role. Lets the sales order line be found from, and reported with, its sales order.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
