INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b7c2014a-f1f6-597c-83d4-d38bf9cee246', '381729f6-0207-554e-9a89-1d273a0a9c22', '0d8c855a-06b1-5951-8d20-4e6ae1ea7b12', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Line Number', 'The line number of the quotation line: a whole number the business records on it. Entered or maintained when a quotation line is created or changed; shown on its form and available to search and reports. Read together with the quotation line''s other fields and its relationships; it is not meaningful on its own. Required: a quotation line cannot be understood without its line number. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
